/// <summary>
/// AVA/WEN/20250109    AVA_012791_CredManBlockExclusionRules
/// </summary>
/// <param name = "_credManTable">CredManTable</param>
public void initFromCredManTable(CredManTable _credManTable)
{
    next initFromCredManTable(_credManTable);

    this.AVANetTotal = _credManTable.AVANetTotal;
}

/// <summary>
/// AVA/WEN/20250109    AVA_012791_CredManBlockExclusionRules
/// </summary>
/// <param name = "_salesTotals">SalesTotals</param>
public void initFromSalesTotals(SalesTotals _salesTotals)
{
    next initFromSalesTotals(_salesTotals);

    this.AVANetTotal = CurrencyExchangeHelper::mstAmount(
                            _salesTotals.totalBalance() + _salesTotals.totalMarkup(),
                            _salesTotals.currencyCode(), 
                               DateTimeUtil::getSystemDate(DateTimeUtil::getUserPreferredTimeZone()),
                               Currency::noYes2UnknownNoYes(_salesTotals.triangulation()),
                               _salesTotals.exchRate(),
                               _salesTotals.exchRateSecondary());
}
